"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from "react";
import { usePrefersReducedMotion } from "@/components/fx/use-media-query";
import { useRole } from "@/components/site/RoleProvider";
import type { RoleKey } from "@/content/schema";
import { SECTOR_FROM } from "@/lib/role-accent";

/** Portrait of each role (772×924, generated by scripts/generate-role-portraits.mjs). */
export const ROLE_IMAGE: Record<RoleKey, string> = {
  fullstack: "/images/roles/role-developer.webp",
  techlead: "/images/roles/role-techlead.webp",
  pm: "/images/roles/role-pm.webp",
};

const SWEEP_MS = 650;
const easeOutCubic = (t: number) => 1 - Math.pow(1 - t, 3);

type Stage = {
  /** Chosen role (from the URL). */
  role: RoleKey;
  /** Role whose portrait is on the base layer. Trails `role` while the select sweep runs. */
  base: RoleKey;
  /** Role under the pointer (arc, slice or panel), if any. */
  hover: RoleKey | null;
  /** Role that is lit: hover first, then the chosen one. Arcs, panels and leader lines follow it. */
  active: RoleKey;
  /** Target of the running select sweep. */
  sweeping: RoleKey | null;
  /** Portrait shown on the peek layer. */
  peekRole: RoleKey;
  reduced: boolean;
  setHover: (key: RoleKey | null) => void;
  select: (key: RoleKey) => void;
  peekRef: RefObject<HTMLDivElement | null>;
  baseImgRef: RefObject<HTMLImageElement | null>;
};

const StageContext = createContext<Stage | null>(null);

/** The wheel, the panels and the leader lines share one stage. Null outside a RoleStageProvider. */
export function useOptionalStage(): Stage | null {
  return useContext(StageContext);
}

export function useStage(): Stage {
  const stage = useContext(StageContext);
  if (!stage) throw new Error("useStage must be used inside RoleStageProvider");
  return stage;
}

function setPeekVars(el: HTMLElement, from: number, sweep: number) {
  el.style.setProperty("--from", `${from}deg`);
  el.style.setProperty("--sweep", `${sweep}deg`);
}

/**
 * Hover and select state of the hero role wheel.
 *
 * The peek layer is a second portrait masked by `conic-gradient(from var(--from), #000 0 var(--sweep), transparent 0)`.
 * Hover shows a 120° slice of the hovered role. Selecting a role calls `setRole` at once (title, accent, URL), then
 * widens the slice from 120° to 360° around its centre in 650 ms (easeOutCubic). The angles are written to CSS
 * variables from requestAnimationFrame, never to React state. When the sweep ends the base layer takes the new
 * portrait and, once that image is decoded, the peek layer is cleared. Under reduced motion the base swaps at once.
 * A role change that does not come from the wheel (URL, another switcher) also swaps the base at once.
 */
export function RoleStageProvider({ children }: { children: ReactNode }) {
  const { role, setRole } = useRole();
  const reduced = usePrefersReducedMotion();
  const [base, setBase] = useState<RoleKey>(role);
  const [sweeping, setSweeping] = useState<RoleKey | null>(null);
  const [hover, setHoverState] = useState<RoleKey | null>(null);
  const hoverRef = useRef<RoleKey | null>(null);
  const sweepRef = useRef<{ target: RoleKey; frame: number } | null>(null);
  const peekRef = useRef<HTMLDivElement | null>(null);
  const baseImgRef = useRef<HTMLImageElement | null>(null);

  // Snap the base to the chosen role when no sweep is running (reduced motion, URL changes, end of a sweep).
  if (sweeping === null && base !== role) setBase(role);

  const setHover = useCallback((key: RoleKey | null) => {
    if (hoverRef.current === key) return;
    hoverRef.current = key;
    setHoverState(key);
  }, []);

  const select = useCallback(
    (key: RoleKey) => {
      const running = sweepRef.current;
      if (key === role && !running) return;
      if (running) {
        // A new choice during a sweep: finish the old one at once and start from there.
        cancelAnimationFrame(running.frame);
        sweepRef.current = null;
        if (running.target === key) return;
        setBase(running.target);
      }
      setRole(key);
      const peek = peekRef.current;
      if (reduced || !peek || typeof requestAnimationFrame !== "function") {
        setSweeping(null);
        return;
      }
      setSweeping(key);
      const center = SECTOR_FROM[key] + 60;
      const start = performance.now();
      // performance.now() rather than the rAF timestamp: same clock as `start`, so the first frame is never negative.
      const step = () => {
        const k = Math.min(1, Math.max(0, (performance.now() - start) / SWEEP_MS));
        const sweep = 120 + 240 * easeOutCubic(k);
        setPeekVars(peek, center - sweep / 2, sweep);
        if (k < 1) {
          sweepRef.current = { target: key, frame: requestAnimationFrame(step) };
        } else {
          sweepRef.current = null;
          setBase(key);
        }
      };
      sweepRef.current = { target: key, frame: requestAnimationFrame(step) };
    },
    [role, setRole, reduced],
  );

  // End of a sweep: the base now shows the target. Keep the full peek on top until the base image is decoded,
  // so the swap never flashes the old portrait, then hand the peek layer back to hover.
  useEffect(() => {
    if (sweeping === null || base !== sweeping || sweepRef.current) return;
    let live = true;
    const img = baseImgRef.current;
    const ready = img && typeof img.decode === "function" ? img.decode() : Promise.resolve();
    ready
      .catch(() => {})
      .then(() => {
        if (live) setSweeping(null);
      });
    return () => {
      live = false;
    };
  }, [base, sweeping]);

  // Hover peek: a 120° slice of the hovered role, or nothing. The sweep owns the variables while it runs.
  useEffect(() => {
    const peek = peekRef.current;
    if (!peek || sweeping !== null) return;
    if (hover && hover !== base) setPeekVars(peek, SECTOR_FROM[hover], 120);
    else setPeekVars(peek, 0, 0);
  }, [hover, base, sweeping]);

  useEffect(() => () => cancelAnimationFrame(sweepRef.current?.frame ?? 0), []);

  const value = useMemo<Stage>(
    () => ({
      role,
      base,
      hover,
      active: hover ?? role,
      sweeping,
      peekRole: sweeping ?? hover ?? base,
      reduced,
      setHover,
      select,
      peekRef,
      baseImgRef,
    }),
    [role, base, hover, sweeping, reduced, setHover, select],
  );

  return <StageContext value={value}>{children}</StageContext>;
}
